// Desligado é uma saída normal e não acessa bancos/provedores.
const c=$input.first().json;
if(c.habilitado!==true)return [];
for(const chave of ['crm_base_interna','jev_url']) {
 const url=String(c[chave]??'');
 const autoridade=url.split('://')[1]?.split(/[/?#]/)[0]??'';
 if(!(url.startsWith('https://')||url.startsWith('http://'))||!autoridade||autoridade.includes('@')||/\s/.test(url))throw Error('EV17_URL_INVALIDA_'+chave);
}
// 60 minutos é o padrão, não um mínimo obrigatório: qualquer inteiro positivo é aceito.
if(!Number.isInteger(c.inatividade_minutos)||c.inatividade_minutos<1)throw Error('EV17_INATIVIDADE_INVALIDA');
if(!Number.isInteger(c.tamanho_lote)||c.tamanho_lote<1||c.tamanho_lote>500)throw Error('EV17_LOTE_INVALIDO');
if(typeof c.modo_teste!=='boolean'||typeof c.jev_modelo!=='string'||!c.jev_modelo.trim())throw Error('EV17_CONFIG_INVALIDA');
if(!Number.isFinite(c.confianca_minima)||c.confianca_minima<0||c.confianca_minima>1)throw Error('EV17_CONFIANCA_INVALIDA');
if(!Number.isInteger(c.limite_contexto_caracteres)||c.limite_contexto_caracteres<1000)throw Error('EV17_LIMITE_CONTEXTO_INVALIDO');
let telefone=String(c.telefone_teste??'').replace(/\D/g,'');
if(telefone.startsWith('55')&&[12,13].includes(telefone.length))telefone=telefone.slice(2);
if(c.modo_teste&&![10,11].includes(telefone.length))throw Error('EV17_TELEFONE_TESTE_OBRIGATORIO');
return [{json:{...c,telefone_filtro:telefone,chave_cursor:c.modo_teste?'EV17:TESTE:'+telefone:'EV17:PRODUCAO'}}];

