// Nomes/IDs são dados do CRM, sem catálogo hardcoded nem prompt versionado inventado.
const r=$('Buscar catálogo de etapas').first().json;
const etapas=r.body;
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(r.statusCode!==200||!Array.isArray(etapas)||etapas.length<1||etapas.length>254)throw Error('EV17_CATALOGO_INDISPONIVEL');
const ids=new Set(),nomes=new Set();
for(const e of etapas) {
 const nome=typeof e.nome==='string'?e.nome.trim():'';
 if(!uuid.test(String(e.id))||!nome||nome==='__SEM_MUDANCA__'||!Number.isFinite(Number(e.ordem)))throw Error('EV17_CATALOGO_INVALIDO');
 const chave=nome.toLocaleLowerCase('pt-BR');
 if(ids.has(String(e.id).toLowerCase())||nomes.has(chave))throw Error('EV17_CATALOGO_AMBIGUO');
 ids.add(String(e.id).toLowerCase());nomes.add(chave);
}
const catalogo=etapas.map(e=>({id:String(e.id),nome:e.nome.trim(),ordem:Number(e.ordem),resultado:e.resultado??null})).sort((a,b)=>a.ordem-b.ordem);
const itens=$('Buscar página de inatividade IA').first().json.itens;
if(!Array.isArray(itens))throw Error('EV17_PAGINA_INVALIDA');
return itens.map(candidato=>({json:{...candidato,catalogo}}));

// .item respeita o atendimento desta iteração; não usar .first() de outro lead.
const r=$input.first().json;
const candidato=$('Loop atendimentos').item.json;
return [{json:{...candidato,reservado:r.execucaoId===String($execution.id)&&r.estado==='RESERVADO'}}];

// Histórico do MESMO lead, como no EV05, incluindo IA e humanos. Não é resumo.
const c=$('Validar parâmetros').first().json;
const candidato=$('Conferir dono da reserva').item.json;
const memoria=$input.first().json;
const base={...candidato,podeAnalisar:false,podeAplicar:false,resultado:'CONTEXTO_MUDOU'};
if(memoria.vigente!==true)return [{json:base}];
const instante=Date.parse(candidato.ultimaIaEm);
if(!Number.isFinite(instante)||Date.now()-instante<c.inatividade_minutos*60000)return [{json:base}];
if(!Array.isArray(memoria.mensagens)||!Number.isInteger(memoria.totalMensagens)||!memoria.contextoAte)throw Error('EV17_MEMORIA_INVALIDA');
const mensagens=memoria.mensagens.map(m=>({remetenteTipo:m.remetenteTipo,tipo:m.tipo,conteudo:typeof m.conteudo==='string'?m.conteudo:'',enviadoEm:m.enviadoEm}));
if(!mensagens.some(m=>m.conteudo.trim()))return [{json:{...base,resultado:'SEM_TEXTO'}}];
const etapaAtual=candidato.catalogo.find(e=>e.id===candidato.etapaAtualId)??null;
const criteria=Object.fromEntries(candidato.catalogo.map(e=>[e.nome,{nome:e.nome,ordem:e.ordem,resultado:e.resultado}]));
criteria.__SEM_MUDANCA__='Não existe evidência suficiente para mudar a etapa atual.';

// A consulta preserva até 500 mensagens para revalidar concorrência. Para o JEV,
// enviamos somente a janela recente que couber no orçamento de caracteres.
// Isso evita que uma conversa longa transforme uma análise válida em erro 400.
const criarCorpo=(janela)=>({
  model:c.jev_modelo,
  state:{etapaAtual:etapaAtual?{nome:etapaAtual.nome,ordem:etapaAtual.ordem,resultado:etapaAtual.resultado}:null,mensagens:janela},
  questions:{etapa:{type:'choice',instructions:c.instrucao_etapa,criteria}}
});
const selecionarJanela=(limite)=>{
  let janela=[];
  // Percorre do fim para o início: a mensagem mais recente sempre tem prioridade.
  for(let indice=mensagens.length-1;indice>=0;indice--){
    const tentativa=[mensagens[indice],...janela];
    if(JSON.stringify(criarCorpo(tentativa)).length<=limite){janela=tentativa;continue;}
    // Uma mensagem isolada pode ser maior que o limite. Conservamos o final dela,
    // que normalmente contém a informação ou pergunta mais recente do lead.
    if(janela.length===0){
      let parcial={...mensagens[indice]};
      while(parcial.conteudo.length&&JSON.stringify(criarCorpo([parcial])).length>limite){
        const excesso=JSON.stringify(criarCorpo([parcial])).length-limite;
        parcial={...parcial,conteudo:parcial.conteudo.slice(Math.min(parcial.conteudo.length,Math.max(1,excesso+64)))};
      }
      if(JSON.stringify(criarCorpo([parcial])).length<=limite)janela=[parcial];
    }
    break;
  }
  return criarCorpo(janela);
};

// Três tamanhos progressivos: a primeira tentativa mantém o máximo de contexto seguro;
// as próximas só são usadas se o provedor ainda declarar max_tokens_exceeded.
const limitePrimario=c.limite_contexto_caracteres;
const limiteReduzido=Math.min(9000,limitePrimario);
const limiteMinimo=Math.min(4000,limiteReduzido);
const corpoJev=selecionarJanela(limitePrimario);
const corpoJevReduzido=selecionarJanela(limiteReduzido);
const corpoJevMinimo=selecionarJanela(limiteMinimo);
if(corpoJev.state.mensagens.length===0)return [{json:{...base,resultado:'SEM_TEXTO'}}];
return [{json:{...base,podeAnalisar:true,totalMensagens:memoria.totalMensagens,contextoAte:memoria.contextoAte,mensagensEnviadasJev:corpoJev.state.mensagens.length,caracteresCorpoJev:JSON.stringify(corpoJev).length,corpoJev,corpoJevReduzido,corpoJevMinimo}}];

// Sem parsing de texto livre: Choice tem resposta tipada e opções fechadas.
const p=$('Preparar decisão JEV').item.json;
const c=$('Validar parâmetros').first().json;
const r=$input.first().json;
const base={...p,corpoJev:undefined,podeAplicar:false,resultado:'ERRO_JEV',httpStatus:Number(r.statusCode??0)};
const b=r.body,escolha=b?.answers?.etapa;
if(r.statusCode!==200||!b||typeof b.model!=='string'||!escolha||escolha.type!=='choice'||typeof escolha.choice!=='string')return [{json:base}];
const opcoes=p.corpoJev.questions.etapa.criteria;
if(!Object.hasOwn(opcoes,escolha.choice)||!Number.isFinite(escolha.confidence)||escolha.confidence<0||escolha.confidence>1)return [{json:base}];
const probs=escolha.probabilities;
const chaves=Object.keys(opcoes);
if(!probs||typeof probs!=='object'||Array.isArray(probs)||Object.keys(probs).length!==chaves.length
 ||!chaves.every(k=>Object.hasOwn(probs,k)&&Number.isFinite(probs[k])&&probs[k]>=0&&probs[k]<=1)
 ||Math.abs(chaves.reduce((s,k)=>s+probs[k],0)-1)>0.000001)return [{json:base}];
const extra={modelo:b.model,confianca:escolha.confidence,inputTokens:Number.isInteger(b.usage?.input_tokens)?b.usage.input_tokens:null,outputTokens:Number.isInteger(b.usage?.output_tokens)?b.usage.output_tokens:null};
if(escolha.confidence<c.confianca_minima)return [{json:{...base,...extra,resultado:'BAIXA_CONFIANCA'}}];
let etapa;
let resultado='DECISAO_VALIDA';
if(escolha.choice==='__SEM_MUDANCA__'){
  // Sem etapa no CRM não pode permanecer sem etapa só porque a IA não viu evidência
  // para avançar o funil. Aplicamos a primeira etapa do catálogo, definida pelo CRM.
  if(p.etapaAtualId)return [{json:{...base,...extra,resultado:'SEM_EVIDENCIA'}}];
  etapa=[...p.catalogo].sort((a,b)=>a.ordem-b.ordem)[0]??null;
  resultado='ETAPA_INICIAL_SEM_EVIDENCIA';
}else{
  etapa=p.catalogo.find(e=>e.nome===escolha.choice)??null;
}
if(!etapa)return [{json:base}];
// Mesmo quando a etapa já coincide, enviamos o POST idempotente ao CRM.
// Isso reconcilia uma eventual divergência entre o fluxo e a tela administrativa.
const corte=p.ultimaIaEm.replace(/[^0-9A-Za-z]/g,'');
return [{json:{...base,...extra,podeAplicar:true,resultado,etapaId:etapa.id,chaveCrm:'ev17-etapa-'+p.atendimentoId+'-'+p.ultimaIaId+'-'+corte+'-'+etapa.id}}];

const p=$('Validar escolha do JEV').item.json;
const vigente=$input.first().json.vigente===true;
return [{json:{...p,podeAplicar:vigente,resultado:vigente?'AGUARDANDO_CRM':'CONTEXTO_MUDOU'}}];

const p=$('Conferir revalidação final').item.json;
if($input.first().json.atendimentoId!==p.atendimentoId)throw Error('EV17_ESCOLHA_NAO_PERSISTIDA');
return [{json:{escolhaPersistida:true}}];

// Never Error não é sucesso. Uma resposta incerta exige reconciliação, sem outra IA.
const p=$('Conferir revalidação final').item.json;
const r=$input.first().json;
const status=Number(r.statusCode??0),b=r.body;
const valido=status===200&&b?.leadId===p.leadId&&b?.etapaId===p.etapaId&&typeof b?.alterado==='boolean';
return [{json:{...p,httpStatus:status,resultado:valido?(b.alterado?'ALTERADA':'SEM_ALTERACAO'):(status===0||status>=500||(status>=200&&status<300)?'RECONCILIAR_CRM':'ERRO_CRM')}}];

// Uma entrada por caminho. Nunca persistir conversa, token ou resposta bruta do provedor.
const p=$input.first().json;
return [{json:{atendimentoId:p.atendimentoId,leadId:p.leadId,ultimaIaId:p.ultimaIaId,ultimaIaEm:p.ultimaIaEm,
 resultado:p.resultado??'ERRO_INTERNO',etapaId:p.etapaId??null,chaveCrm:p.chaveCrm??null,modelo:p.modelo??null,
 confianca:Number.isFinite(p.confianca)?p.confianca:null,httpStatus:Number.isInteger(p.httpStatus)?p.httpStatus:null,
 inputTokens:Number.isInteger(p.inputTokens)?p.inputTokens:null,outputTokens:Number.isInteger(p.outputTokens)?p.outputTokens:null}}];

// Falha de leitura/preparo não interrompe os outros leads e não vira sucesso.
const p=$('Conferir dono da reserva').item.json;
return [{json:{...p,resultado:'ERRO_CONTEXTO'}}];
